for id,emp,year,pos,cat,note in data:
 p=next(p for p in faculty if p['id']==id);doc=next(d for d in json.loads((root/f'research/placements-a/documents/{id}.json').read_text(encoding='utf-8'))['documents'] if d.get('kind')=='pdf')
 add(p['name'],emp,year,doc['url'],p['name']+' — Curriculum Vitae',note=note,position=pos,category=cat,start=year)
 records[-1]['reason']='Faculty CV degree and employment chronology establishes the first post-PhD appointment.'
 if p['phdYear']!=year:records[-1]['phdYearResolution']='The faculty CV explicitly dates the completed doctorate to '+str(year)+'. Original imported value retained separately.'
for id,reason in [('omlist-1f05702f28357186','CV lists two doctorates completed in 2015, SKEMA employment 2009–2016 and Ipag employment 2015–2016 without titles or months. Overlap makes the first post-PhD role ambiguous.'),('omlist-23b71cb5794fc02b','CV lists PhD June 2006 and overlapping MIT and IBM postdoctoral appointments in 2006–2007, plus MIT summer 2006. Exact first appointment ordering needs confirmation.')]:
 p=next(p for p in faculty if p['id']==id);doc=next(d for d in json.loads((root/f'research/placements-a/documents/{id}.json').read_text(encoding='utf-8'))['documents'] if d.get('kind')=='pdf')
 records.append(dict(facultyId=id,name=p['name'],status='unresolved',checkedAt='2026-10-16',reason=reason,sources=[dict(url=doc['url'],title=p['name']+' — Curriculum Vitae',notes='Degree and career chronology reviewed; overlapping appointments prevent exact ordering.')]))
